use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Merge file favor options for `MergeOptions` instruct the file-level"] # [doc = " merging functionality how to deal with conflicting regions of the files."] # [derive (PartialEq , Eq , Debug , Copy , Clone)] pub enum FileFavor { # [doc = " When a region of a file is changed in both branches, a conflict will be"] # [doc = " recorded in the index so that git_checkout can produce a merge file with"] # [doc = " conflict markers in the working directory. This is the default."] Normal , # [doc = " When a region of a file is changed in both branches, the file created"] # [doc = " in the index will contain the \"ours\" side of any conflicting region."] # [doc = " The index will not record a conflict."] Ours , # [doc = " When a region of a file is changed in both branches, the file created"] # [doc = " in the index will contain the \"theirs\" side of any conflicting region."] # [doc = " The index will not record a conflict."] Theirs , # [doc = " When a region of a file is changed in both branches, the file created"] # [doc = " in the index will contain each unique line from each side, which has"] # [doc = " the result of combining both files. The index will not record a conflict."] Union , }